def dpll(cnf, assignment):
    def propagate():
        changed = False
        for clause in cnf:
            if len(clause) == 1:
                literal = clause[0]
                var = abs(literal)
                if literal > 0 and var not in assignment:
                    assignment[var] = True
                    changed = True
                elif literal < 0 and var not in assignment:
                    assignment[var] = False
                    changed = True
        return changed

    def unit_propagation():
        while propagate():
            pass

    def pure_literal_sweep(literal):
        for clause in cnf:
            if literal in clause:
                clause.remove(literal)
                if len(clause) == 0:
                    return False
            elif -literal in clause:
                clause.remove(-literal)
        return True

    while True:
        unit_propagation()
        changed = False
        for var in range(1, max(assignment.keys()) + 1):
            if var not in assignment:
                if pure_literal_sweep(var) and pure_literal_sweep(-var):
                    continue
                else:
                    assignment[var] = True
                    changed = True
        if not changed:
            return assignment

def generate_3cnf(n, m):
    cnf = set()
    while len(cnf) < m:
        clause = {random.randint(1, n), random.randint(-n, -1)}
        if len(clause) == 2 and all(abs(lit) not in clause for lit in cnf):
            cnf.add(tuple(sorted(clause)))
    return cnf

