import random
import math
from fractions import Fraction

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    return abs(a*b) // gcd(a, b)

def matrix_multiply(A, B):
    m, n, p = len(A), len(B[0]), len(B)
    C = [[Fraction(0) for _ in range(p)] for _ in range(m)]
    for i in range(m):
        for j in range(p):
            for k in range(n):
                C[i][j] += A[i][k] * B[k][j]
    return C

def gaussian_elimination(A, b):
    n = len(A)
    M = [A[i] + [b[i]] for i in range(n)]
    for i in range(n):
        max_row = i
        for j in range(i+1, n):
            if abs(M[j][i]) > abs(M[max_row][i]):
                max_row = j
        M[i], M[max_row] = M[max_row], M[i]
        factor = M[i][i]
        for j in range(i, n + 1):
            M[i][j] /= factor
        for j in range(n):
            if i != j:
                factor = M[j][i]
                for k in range(i, n + 1):
                    M[j][k] -= factor * M[i][k]
    return [M[i][-1] for i in range(n)]

def hessian_rank(p_F, n):
    H_F = [[Fraction(0) for _ in range(n)] for _ in range(n)]
    for x in range(3**n):
        x_vec = [(x // (3 ** i)) % 3 for i in range(n)]
        for i in range(n):
            for j in range(i, n):
                H_F[i][j] += p_F[x_vec] * (-1)**(x_vec[i] + x_vec[j])
                if i != j:
                    H_F[j][i] = H_F[i][j]
    rank = 0
    for row in H_F:
        if any(row):
            rank += 1
    return rank

def lex_dpll(F, n):
    def dpll(assignment):
        unsatisfied_clauses = [C for C in F if not any(l == assignment[i] for i, l in enumerate(C))]
        if not unsatisfied_clauses:
            return True
        unit_clause = next((C for C in unsatisfied_clauses if len(C) == 1), None)
        if unit_clause:
            literal = unit_clause[0]
            if literal < 0:
                literal = -literal
                assignment[literal-1] = 0
            else:
                assignment[literal-1] = 1
            return dpll(assignment)
        for literal in range(1, n+1):
            if literal not in [abs(l) for l in assignment]:
                new_assignment = assignment[:]
                new_assignment.append(literal)
                if dpll(new_assignment):
                    return True
                if -literal not in [abs(l) for l in assignment]:
                    new_assignment = assignment[:]
                    new_assignment.append(-literal)
                    if dpll(new_assignment):
                        return True
        return False
    return dpll([0]*n)

